// Planning du jour : calcule l'heure du brief (40 min avant le premier cours).
// Emploi du temps recopié depuis le vault : "BTS SIO/Emploi du temps BTS SIO2".
// Si l'emploi du temps change, modifier SCHEDULE ici (le 3e champ true = cours optionnel, ignoré).
const PARIS = 'Europe/Paris';
const AVANCE_MIN = 40;          // minutes avant le premier cours
const HEURE_SANS_COURS = [9, 0]; // heure du brief les jours sans cours
// Début exact non noté : seule la fin compte. Toussaint 2026 : reprise le lundi 2 novembre.
const VACANCES = [['2026-10-01', '2026-11-01']];
const SCHEDULE = {
    1: [['08:50', 'Aide individualisée', true], ['10:00', 'Anglais'], ['10:50', 'Maths'], ['12:30', 'SISR'], ['16:10', 'CEJM']],
    2: [['08:00', 'Atelier mathématiques'], ['08:50', 'Mathématiques'], ['10:00', 'SISR'], ['14:10', 'Anglais'], ['15:20', 'Culture générale']],
    3: [['12:30', 'Aide individualisée', true], ['13:20', 'CEJM'], ['15:20', 'Mathématiques'], ['16:10', 'Culture générale']],
    4: [['08:25', 'Cybersécurité'], ['10:50', 'Cybersécurité'], ['13:20', 'CEJM'], ['15:20', 'SISR']],
    5: [['08:00', 'Ateliers pro SISR'], ['10:00', 'Ateliers pro SISR'], ['13:20', 'CEJM'], ['15:20', 'Support et mise à disposition de services informatiques']]
};
const JOURS = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const MOIS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];

function heureParis(d) {
    const p = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: PARIS, year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23'
    }).formatToParts(d).forEach(x => { p[x.type] = x.value; });
    return p;
}
const iso = d => d.toISOString().slice(0, 10);
const enVacances = s => VACANCES.some(([a, b]) => s >= a && s <= b);
function coursDu(jour) {                       // jour : Date en "heure murale" (UTC)
    if (enVacances(iso(jour))) { return []; }
    const liste = (SCHEDULE[jour.getUTCDay()] || []).filter(c => !c[2]);
    return liste.filter((c, i) => i === 0 || c[1] !== liste[i - 1][1]); // fusionne deux créneaux de suite
}

const now = msg.now ? new Date(msg.now) : new Date();
const p = heureParis(now);
const murale = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second);
const aujourdhui = new Date(Date.UTC(+p.year, +p.month - 1, +p.day));
const cours = coursDu(aujourdhui);

const jourMs = [+p.year, +p.month - 1, +p.day];
let brief, rappel = null;
if (cours.length) {
    const [h, m] = cours[0][0].split(':').map(Number);
    const avant = Date.UTC(...jourMs, h, m - AVANCE_MIN);       // premier cours - 40 min
    const matin = Date.UTC(...jourMs, HEURE_SANS_COURS[0], HEURE_SANS_COURS[1]);
    brief = Math.min(avant, matin);                              // le brief reste un brief du matin
    if (avant - brief >= 10 * 60000) { rappel = avant; }         // sinon le brief fait déjà office de rappel
} else {
    brief = Date.UTC(...jourMs, HEURE_SANS_COURS[0], HEURE_SANS_COURS[1]);
}

let prochain = null;
if (!cours.length) {
    for (let i = 1; i <= 14 && !prochain; i++) {
        const j = new Date(aujourdhui.getTime() + i * 86400000);
        const c = coursDu(j);
        if (c.length) {
            prochain = { jour: `${JOURS[j.getUTCDay()]} ${j.getUTCDate()} ${MOIS[j.getUTCMonth()]}`, heure: c[0][0], nom: c[0][1] };
        }
    }
}

msg.plan = {
    date: `${JOURS[aujourdhui.getUTCDay()]} ${aujourdhui.getUTCDate()} ${MOIS[aujourdhui.getUTCMonth()]}`,
    cours: cours.map(c => ({ heure: c[0], nom: c[1] })),
    prochain
};
const hm = t => { const d = new Date(t); return String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); };
const envois = [];
if (msg.test) {
    envois.push({ kind: 'brief', delay: 0 });
} else {
    if (brief >= murale) { envois.push({ kind: 'brief', delay: brief - murale }); }
    if (rappel !== null && rappel >= murale) { envois.push({ kind: 'rappel', delay: rappel - murale }); }
}
if (!envois.length) {
    node.status({ fill: 'grey', shape: 'ring', text: 'heures déjà passées' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: 'brief ' + hm(brief) + (rappel !== null ? ', rappel ' + hm(rappel) : '') });
envois.forEach(e => node.send(Object.assign({}, msg, e, { plan: Object.assign({}, msg.plan, { minutes: AVANCE_MIN }) })));
return null;

// Rédiger le brief : transforme le planning et la météo en phrase à dire à voix haute.
const MICRO = 'media_player.chambre_tom';
const VOIX = 'tts.google_translate_en_com'; // voix Google Translate, langue forcée en français plus bas
const METEO = {
    'clear-night': 'ciel dégagé', 'cloudy': 'nuageux', 'exceptional': 'conditions exceptionnelles',
    'fog': 'brouillard', 'hail': 'grêle', 'lightning': 'orageux', 'lightning-rainy': 'orages et pluie',
    'partlycloudy': 'partiellement nuageux', 'pouring': 'forte pluie', 'rainy': 'pluvieux',
    'snowy': 'neigeux', 'snowy-rainy': 'neige fondue', 'sunny': 'ensoleillé',
    'windy': 'venteux', 'windy-variant': 'venteux et nuageux'
};
const dire = hhmm => {
    const [h, m] = hhmm.split(':').map(Number);
    return m ? `${h} heures ${m}` : `${h} heures`;
};

const plan = msg.plan;
let texte;

if (msg.kind === 'rappel') {
    texte = `Rappel : ton premier cours, ${plan.cours[0].nom}, commence à ${dire(plan.cours[0].heure)}, dans ${plan.minutes} minutes.`;
} else {
    const attr = (msg.data && msg.data.attributes) || {};
    const etat = msg.payload;
    texte = `Bonjour Tom. Nous sommes ${plan.date}.`;

    if (typeof attr.temperature === 'number') {
        texte += ` Dehors, il fait ${Math.round(attr.temperature)} degrés`;
        texte += METEO[etat] ? `, ${METEO[etat]}.` : '.';
    }

    if (plan.cours.length) {
        texte += ' Aujourd\'hui, tu as : ' + plan.cours.map(c => `${c.nom} à ${dire(c.heure)}`).join(', ') + '.';
        texte += ` Ton premier cours commence à ${dire(plan.cours[0].heure)}. Bonne journée !`;
    } else if (plan.prochain) {
        texte += ` Pas de cours aujourd'hui. Prochain cours : ${plan.prochain.jour}, à ${dire(plan.prochain.heure)}. Profite de ta journée !`;
    } else {
        texte += ' Pas de cours aujourd\'hui. Profite de ta journée !';
    }
}

msg.brief = texte;
msg.payload = {
    action: 'tts.speak',
    target: { entity_id: [VOIX] },
    data: { media_player_entity_id: MICRO, message: texte, language: 'fr' }
};
return msg;
